[standards/application/monitoring/STD-APP-MON-001-monitoring-observability.md#frontend-rum-implementation]

#### Frontend RUM Implementation

```typescript
// React application monitoring setup
import { dynatrace } from '@dynatrace/browser-agent';

// Initialize DynaTrace RUM
dynatrace({
    appId: 'enterprise-portal',
    allowedOrigins: ['https://*.enterprise.com'],
    userTracking: {
        enabled: true,
        persistentSessionId: true,
        cookieSameSite: 'Strict',
    },
    distributedTracingHeader: true,
    performanceMonitoring: {
        enabled: true,
        maxEventCount: 1000,
    },
    privacyPolicy: {
        maskTextInputs: true,
        maskUserInput: true,
        recordUserSessions: false,
    },
});

// Custom user action tracking
interface UserActionContext {
    tenantId: string;
    userId?: string;
    feature: string;
    [key: string]: any;
}

function trackUserAction(action: string, context: UserActionContext) {
    dynatrace.sendBrowserEvent({
        eventType: action,
        tenantId: context.tenantId,
        userId: context.userId,
        feature: context.feature,
        timestamp: Date.now(),
        ...context,
    });
}

// Performance tracking for critical user journeys
function trackCriticalUserJourney(journeyName: string, stepName: string) {
    const startTime = performance.now();

    return {
        complete: () => {
            const duration = performance.now() - startTime;
            dynatrace.sendBrowserEvent({
                eventType: 'critical_journey_step',
                journeyName,
                stepName,
                duration,
                timestamp: Date.now(),
            });
        },
        fail: (error: string) => {
            dynatrace.sendBrowserEvent({
                eventType: 'critical_journey_error',
                journeyName,
                stepName,
                error,
                timestamp: Date.now(),
            });
        },
    };
}

// Usage example
const loginJourney = trackCriticalUserJourney('user_authentication', 'credential_submission');
try {
    await submitCredentials();
    loginJourney.complete();
} catch (error) {
    loginJourney.fail(error.message);
}
```

