[standards/application/monitoring/STD-APP-MON-001-monitoring-observability.md#dashboard-configuration-example]

#### Dashboard Configuration Example

```json
{
    "dashboard": {
        "title": "Service Health Dashboard",
        "refreshRate": "1m",
        "timeframe": "last-4-hours",
        "layout": {
            "tiles": [
                {
                    "name": "Service Status",
                    "type": "status-overview",
                    "position": { "x": 0, "y": 0, "width": 12, "height": 4 },
                    "queries": [
                        {
                            "metric": "builtin:service.availability",
                            "aggregation": "avg",
                            "filter": "service.name={{service.name}}"
                        }
                    ]
                },
                {
                    "name": "Error Rates",
                    "type": "line-chart",
                    "position": { "x": 0, "y": 4, "width": 6, "height": 4 },
                    "queries": [
                        {
                            "metric": "builtin:service.errors.total.rate",
                            "aggregation": "avg",
                            "filter": "service.name={{service.name}}"
                        }
                    ]
                },
                {
                    "name": "Response Times",
                    "type": "heatmap",
                    "position": { "x": 6, "y": 4, "width": 6, "height": 4 },
                    "queries": [
                        {
                            "metric": "builtin:service.response.time",
                            "aggregation": "percentile",
                            "percentile": 95,
                            "filter": "service.name={{service.name}}"
                        }
                    ]
                }
            ]
        }
    }
}
```
